<div class="heading"><div><span class="eyebrow">QUICKSALE</span><h1><?= esc($heading) ?></h1></div><?php if(!empty($createUrl)): ?><a class="button primary" href="<?= esc($createUrl) ?>">+ Add new</a><?php endif ?></div><section class="panel" style="overflow:auto"><table><thead><tr><?php foreach($columns as $c): ?><th><?= esc($c['label']) ?></th><?php endforeach ?><?php if(!empty($editBase)||!empty($deleteBase)): ?><th>Actions</th><?php endif ?></tr></thead><tbody><?php if(empty($rows)): ?><tr><td colspan="<?= count($columns)+1 ?>" class="muted">No records yet.</td></tr><?php endif ?><?php foreach($rows as $row): ?><tr><?php foreach($columns as $c): ?><td><?php if(($c['type']??'')==='image'&&!empty($row[$c['name']])): ?><img class="thumb" src="<?= base_url('uploads/'.esc($row[$c['name']])) ?>" alt=""><?php else: ?><?= esc($row[$c['name']]??'-') ?><?php endif ?></td><?php endforeach ?><?php if(!empty($editBase)||!empty($deleteBase)): ?><td><div class="actions"><?php if(!empty($editBase)): ?><a class="button" href="<?= esc($editBase.'/'.$row['id']) ?>">Edit</a><?php endif ?><?php if(!empty($deleteBase)): ?><form method="post" action="<?= esc($deleteBase.'/'.$row['id']) ?>" onsubmit="return confirm('<?= esc($deleteLabel??'Delete') ?> this record?')"><?= csrf_field() ?><button class="button danger"><?= esc($deleteLabel??'Delete') ?></button></form><?php endif ?></div></td><?php endif ?></tr><?php endforeach ?></tbody></table></section>